# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span

class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        labels = round_labels([Span(9 * 60 + 5, 17 * 60 + 12)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = round_labels([Span(0, 75)], 30)
        self.assertEqual(labels, ["00:00-01:30 (1h 30m)"])

    def test_one_label_per_span(self):
        labels = round_labels([Span(0, 60), Span(120, 180)], 30)
        self.assertEqual(len(labels), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
